def cifrar_json_y_backfill_hmac(apps, schema_editor):
    from modulo_prevencion.crypto import calcular_rut_hmac, cifrar_texto, descifrar_texto

    InvestigacionAccidente = apps.get_model('modulo_prevencion', 'InvestigacionAccidente')
    DenunciaLeyKarin = apps.get_model('modulo_prevencion', 'DenunciaLeyKarin')
    RegistroCapacitacion = apps.get_model('modulo_prevencion', 'RegistroCapacitacion')

    cursor = schema_editor.connection.cursor()

    # 1. Cifrar JSON legados y calcular rut_hmac en InvestigacionAccidente
    acc_table = InvestigacionAccidente._meta.db_table
    acc_json_cols = ('causas_inmediatas', 'causas_basicas', 'analisis_5_porques', 'arbol_de_causas')
    cursor.execute(f"SELECT id, rut_afectado, {', '.join(acc_json_cols)} FROM {acc_table}")
    for row in cursor.fetchall():
        pk = row[0]
        raw_rut = descifrar_texto(row[1] or '')
        hmac_val = calcular_rut_hmac(raw_rut)
        updates = {}
        if hmac_val:
            updates['rut_hmac'] = hmac_val
        for idx, col in enumerate(acc_json_cols, start=2):
            raw_val = row[idx]
            if raw_val is None or raw_val == '':
                continue
            raw_str = json.dumps(raw_val, ensure_ascii=False) if isinstance(raw_val, (dict, list)) else str(raw_val)
            if raw_str and not raw_str.startswith('enc:v1:'):
                updates[col] = cifrar_texto(raw_str)
        if updates:
            set_sql = ', '.join(f"{col} = %s" for col in updates.keys())
            cursor.execute(f"UPDATE {acc_table} SET {set_sql} WHERE id = %s", list(updates.values()) + [pk])

    # 2. Calcular rut_hmac en DenunciaLeyKarin
    karin_table = DenunciaLeyKarin._meta.db_table
    cursor.execute(f"SELECT id, rut_denunciante FROM {karin_table}")
    for pk, enc_rut in cursor.fetchall():
        raw_rut = descifrar_texto(enc_rut or '')
        hmac_val = calcular_rut_hmac(raw_rut)
        if hmac_val:
            cursor.execute(f"UPDATE {karin_table} SET rut_hmac = %s WHERE id = %s", [hmac_val, pk])

    # 3. Cifrar asistentes JSON en RegistroCapacitacion
    cap_table = RegistroCapacitacion._meta.db_table
    cursor.execute(f"SELECT id, asistentes FROM {cap_table}")
    for pk, raw_val in cursor.fetchall():
        if raw_val is None or raw_val == '':
            continue
        raw_str = json.dumps(raw_val, ensure_ascii=False) if isinstance(raw_val, (dict, list)) else str(raw_val)
        if raw_str and not raw_str.startswith('enc:v1:'):
            cursor.execute(f"UPDATE {cap_table} SET asistentes = %s WHERE id = %s", [cifrar_texto(raw_str), pk])


